  "note": "设备: S.E.L.M.A.液压爆破弹\n\n特勤干员: 专家Håvard \"ACE\" Haugland\n\n评估负责人:专家Monika \"IQ\" Weiss\n\n我曾对不少攀爬设备进行评估，但Ace的S.E.L.M.A.液压爆破弹仍然出乎我的意料。自动缓降器已经在民用/攀岩爱好领域有所应用，但仍需要手动放置，S.E.L.M.A.在这方面的技术应用截然不同。\n\n附挂的重物突然下降时，设备的外层套管会释放套叠式伸缩长钉(岩钉)。使用者要经过一定的训练才能使设备在投掷后部署在最佳接触位置，但只是经过几次尝试，在熟悉设备的重量与空气动力特性之后，我就相对掌握了这个设备的使用技巧。长钉附带弹药包，里面装有液体和炸药，隐藏在“母壳”中。“母壳”下降至下一处爆破点，弹药包同时展开，准备引爆。\n\n这是用于突破墙体及其他垂直表面的高效爆破工具，对使用者以及等待救援者的风险也降至最低。该设备爆破的缺口大小也利于开展搜救行动，因为设备里的内嵌感应器能监测部署岩钉的伸缩长度，由此测量墙体硬度，并在能够承重的墙体结构上尽力稳固部署。\n\n私营机构能够专研一项技术，且在该项技术上卓有成效，这就是这种专有技术的应用例子。能在其他情境下对这项技术进行测试，我们太幸运了。\n\n————Monika",
  "anecdote": "Ace以挪威国防军成员的身份参加了联合国在索马里的联合行动，并在此次行动中救下了Kali，此后他便受邀加入永夜安港。",
