   "ACE作为游戏中第四位登场的具有强切技能的干员，可以参考Thermite的部分战术。配合队友，面对想要听电的Bandit或Kaid时，可以同时部署多个1，凭借全自动的引爆以及较快的引爆速度，可以至少切开一个用于对枪但无法过人的对枪洞。"
