  "desc": "第707特殊任务营是大韩民国陆军特种作战司令部直属的反恐特战部队，别称白虎部队，1981年4月17日成立。1972年慕尼黑惨案后，韩国政府为保障1988年汉城奥运会安全而筹建该部队，专责应对韩国境内的恐怖袭击、人质营救、要员保护与快速反应任务。队员从现役特种部队成员中择优选拔，淘汰率极高，并长期与美国三角洲部队、英国SAS、德国GSG 9等单位联合训练。2019年2月该部队扩建改编为团级建制，改称第707特殊任务团。",
