  "desc": "秘鲁考古文化保护者协会（APCA）是《彩虹六号：围攻》原创的准军事化公益组织，总部位于秘鲁，由干员 Amaru 领导。该组织以保护秘鲁境内的考古遗址与文化遗产、打击文物盗掘与走私为主要使命，兼具田野护卫与武装巡逻职能。Amaru 及组织成员凭借在高海拔与丛林环境中的野外作业、攀爬与索降专长被招募进入彩虹小队。",
