  "desc": "特别警察行动营（BOPE）是巴西里约热内卢州军事警察（宪兵）下属的特种警察部队，1978年成立。该营专责在里约热内卢贫民窟等高风险城区执行武装突入、高危险逮捕令执行、人质营救与缉毒攻坚任务，配备装甲车辆与重型武器。BOPE 队员需通过严苛的选拔与训练，以在复杂城市地形和密集居民区中作战著称。在《围攻》中，Capitão 与 Caveira 出自该部队。",
