  "desc": "特种部队群（SFG）是比利时陆军地面部队的特种作战单位，隶属特种作战团（SOR），驻地在海弗莱（Heverlee）。其沿革可追溯至二战时期的比利时SAS中队；2000年4月以特种部队连形式组建，2003年2月成为独立单位。2011年12月，SFG 继承第1伞兵营的旗帜、徽章与传统，并沿用 Who Dares Wins、Never Surrender 等格言。主要任务包括特种侦察、直接行动、反恐与人质营救。",
