  "type": "real",
  "founded": "1987",
  "desc": "战术作战司令部（COT）是巴西联邦警察的精英战术单位，1987年投入运作，基地设于巴西利亚。该单位应巴西议会建议组建，专门应对超出常规警力能力的高风险、复杂干预行动，包括反恐、缉毒、在热带雨林与湿地等恶劣地形作战，以及处置境内劫机事件。成员由联邦警察自愿报名，需完成为期14周的战术课程及一年以上的后续训练，选拔淘汰率约六成，平时不间断训练并可随时全国派遣。",
