  "desc": "特别行动小组（GEO）是西班牙国家警察（Cuerpo Nacional de Policía）的精英反恐与人质营救单位，1978年成立，总部位于马德里。GEO 专责处置劫持人质、恐怖袭击、高风险逮捕与要员保护等事件，是西班牙警队中战术能力最高层级的单位，也是欧洲 ATLAS 网络的成员。队员需通过严苛选拔与长期专业训练，涵盖突入、狙击、潜水、伞降等技能。在《彩虹六号：围攻》中，Jackal 与 Mira 出自该部队。",
