  "desc": "紧急应变单位（ERU，爱尔兰语 Aonad Práinnfhreagartha）是爱尔兰国家警察和平卫队（An Garda Síochána）的最高层级武装战术单位，1977年12月15日以「特别任务队」（Special Task Force）名义成立，1987年改称紧急应变单位，总部设于都柏林哈考特街。该单位负责反恐、人质营救、危机谈判、高风险搜捕与要员保护，并与爱尔兰陆军游骑兵联队（ARW）共享设施、联合训练。",
