  "desc": "都市战术反应部队（GSUTR，代号 Grim Sky）是《彩虹六号：围攻》设定中彩虹小队自行组建的城市作战单位，在第三年第三季「暗空行动」中登场。与保留原属单位编制的其他小队不同，GSUTR 专为街道与城市环境下的作战而设，成员国籍与来源单位各异。伦敦警察厅（MPS）警官 Clash 加入该部队，带来人群控制与暴动处置方面的专长，其标志性装备为群控电击护盾（CCE Shield）。",
