  "founded": "1962",
  "desc": "海豹突击队（United States Navy SEALs）是美国海军的特种作战部队，1962年正式组建，隶属美国海军特种作战司令部，主要基地位于加州科罗纳多。SEAL 一词源自其可执行的海（Sea）、空（Air）、陆（Land）三类作战环境，承担直接行动、特种侦察、反恐、人质营救与非常规战争任务，以严苛的基础水下爆破训练（BUD/S）闻名。在《彩虹六号：围攻》第一年更新中，Blackbeard 与 Valkyrie 出自该部队。",
