  "desc": "海军潜水部队（NDU）是新加坡武装部队的精锐海军特种部队，承担水下渗透、爆炸物处理（EOD）、清除潜水（Clearance Diving）与蛙人作战等任务，被视为新加坡最精锐的海军特种单位之一，其蛙人学校（FMS）训练以高强度的体能与耐力要求著称。在《彩虹六号：围攻》中，干员 Grim 曾在新加坡国民服役期间编入 NDU 并完成蛙人学校训练，后转入永夜安港。",
