  "desc": "特种空勤团（SAS）是英国陆军的精锐特种部队，1941年在二战北非战场组建，战后发展为常备的反恐与特种作战单位，驻地在赫里福德。SAS 以「敢做就能赢」（Who Dares Wins）为格言，承担反恐、人质营救、特种侦察与直接行动任务，其选拔体系与战术被多国特种部队效仿，彩虹小队的基地亦设于赫里福。在《彩虹六号：围攻》首发阵容中，Sledge、Thatcher、Smoke、Mute 出自该部队。",
