  "desc": "美国特勤局（United States Secret Service，USSS）是美国联邦执法机构，1865年成立，最初为打击伪造货币而设立，现隶属美国国土安全部。该机构承担两项核心使命：一是保护美国总统、副总统及其家属、前政要与来访外国元首的人身安全；二是调查伪造货币、金融欺诈与网络金融犯罪。在《彩虹六号：围攻》第四年更新中，Warden 作为特勤局干员登场。",
