  "desc": "彩虹小队（Team Rainbow）是汤姆·克兰西《彩虹六号》系列的核心组织，1999年由北约主导成立，是一支受北约直接监督的国际精英反恐部队，总部设于英国赫里福基地。小队从全球各国顶尖的反恐与特种部队中招募精英，以出色的战术与先进装备著称，自成立起阻止了多起恐怖组织阴谋，但于2012年被停用，三年后在代号「六号」（Six）的新领导者手下重组，以打击白面具及其广泛的恐怖袭击。作战人员分为新进干员与特勤干员。",
