// 合并进 OPERATORS，保持与现有干员数据一致的使用方式
(function () {
    if (typeof OPERATORS === 'undefined') return;
    OPERATORS.forEach(o => {
        const l = OPERATOR_LORE[o.name];
        if (!l) return;
        o.bio = l.bio || null;
        o.psych = l.psych || null;
        o.note = l.note || null;
        o.anecdote = l.anecdote || null;
        o.training = l.training || [];
        o.experience = l.experience || [];
        o.relations = l.relations || [];
        o.tips = l.tips || [];
        o.trivia = l.trivia || [];
        o.quotes = l.quotes || [];
        o.org_label = (typeof ORG_LABEL !== 'undefined' && o.affiliation) ? (ORG_LABEL[o.affiliation] || null) : null;
    });
    ORGANIZATIONS.forEach(g => { g.members = g.members || []; });
})();
